INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370963, 15853, 'The Times of India', 'en', 'Rishabh Pant creates history, becomes first Indian to achieve this feat', 'https://timesofindia.indiatimes.com/sports/cricket/india-vs-sri-lanka/rishabh-pant-creates-history-becomes-first-indian-to-achieve-this-feat-in-tests/articleshow/133316107.cms', 'India''s star wicketkeeper batter Rishabh Pant created history on Tuesday during the first Test against Sri Lanka in Galle. The India wicketkeeper-batter became the first Indian cricketer to hit 100 sixes in Test cricket. Pant reached the milestone with a big six off Lahiru Kumara. The shot also brought up his 20th Test fifty.', 'https://static.toiimg.com/photo/msid-133316168,imgsize-27542.cms', '2026-08-18T08:09:05+00:00', '2026-08-18T08:17:47.537785'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
