INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371068, 15857, 'Aaj Tak', 'hi', '17 ख‍िलाड़‍ियों को अर्जुन पुरस्कार, ल‍िस्ट में एक भी क्रिकेटर नहीं', 'https://www.aajtak.in/sports/news/story/national-sports-awards-2025-arjuna-award-winners-full-list-no-cricketers-tspok-dskc-2624697-2026-08-18', 'खेल मंत्रालय ने नेशनल स्पोर्ट्स अवॉर्ड्स 2025 का ऐलान कर दिया है. देश के अलग-अलग खेलों में शानदार परफॉर्मेंस करने वाले प्लेयर्स, कोचों और खेल प्रेमियों को इस बार नेशनल खेल पुरस्कारों से सम्मानित किया जाएगा. पुरस्कारों की घोषणा सुप्रीम कोर्ट के पूर्व जज जस्टिस (रिटायर्ड) अरुण कुमार मिश्रा की अध्यक्षता वाली सिलेक्शन कमेटी की सिफारिशों के आधार पर की गई है.', '', '2026-08-18T07:56:50+00:00', '2026-08-18T08:18:32.231031'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
