INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371895, 15858, 'France 24', 'en', 'Sophie Adenot set to become first French female astronaut to venture outside ISS', 'https://www.france24.com/en/france/20260818-sophie-adenot-set-to-become-first-french-female-astronaut-to-venture-outside-iss', 'The International Space Station (ISS) is set to host the first spacewalk by a French female on Tuesday. Sophie Adenot, 44, will be the second European woman to conduct an extravehicular walk, after Italian astronaut Samantha Cristoforetti''s mission in 2022.', 'https://s.france24.com/media/display/a70683dc-9adc-11f1-bc3b-005056bf30b7/w:1024/p:16x9/3eef87ad9bf68e50ca94f7632fb77315a490ce8d.jpg', '2026-08-18T08:13:12+00:00', '2026-08-18T09:15:08.870215'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
