INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372214, 15858, 'Euronews', 'en', 'Sophie Adenot to become first French woman to conduct spacewalk at ISS', 'http://www.euronews.com/my-europe/2026/08/18/sophie-adenot-to-become-first-french-woman-to-conduct-spacewalk-at-iss', 'The spacewalk is scheduled to start at around 1400 CET and last six and a half hours, with the goal of replacing a space-to-ground antenna on the orbital complex, according to NASA.', '', '2026-08-18T08:37:01+00:00', '2026-08-18T09:19:36.878470'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
