INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (424280, 15861, 'Le Monde', 'en', 'DR Congo tests Ebola treatments and vaccines amid country''s worst-ever epidemic', 'https://www.lemonde.fr/en/environment/article/2026/08/28/treatments-and-vaccines-under-trial-amid-the-worst-ebola-epidemic-in-the-democratic-republic-of-congo-s-history_6756919_114.html', 'More than 2,700 people have died since the official declaration of the epidemic in the Democratic Republic of Congo in mid-May. Health organizations are racing to develop effective therapies, including antivirals, monoclonal antibodies and vaccines.', 'https://img.lemde.fr/2026/08/22/456/0/5759/2879/644/322/60/0/b63776a_ftp-1-h0e2se2jt6gm-5894373-01-06.jpg', '2026-08-28T00:36:36+00:00', '2026-08-28T12:51:44.450229'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
